"use strict";$(".auth-template-action-btn").on("click",function(){$(this).toggleClass("text-dark"),$(this).closest(".single-auth-template").find(".settings").toggleClass("active")}),$(".imgbgchk").on("change",function(){const e=$(this).val(),a=authSettings[e];let i="";if(a.required.includes("title")&&(i+=`<div class="mv-form-grid__cell mv-form-grid__cell--full"><div class="form-group row">\n            <label for="title" class="control-label ltr:ps-3 rtl:pe-3">${jsLang("Title")}</label>\n            <div class="col-sm-12">\n                <input type="text" class="form-control form-width inputFieldDesign" id="title" name="title" value="${a.data.title}">\n            </div>\n        </div></div>`),a.required.includes("description")&&(i+=`<div class="mv-form-grid__cell mv-form-grid__cell--full"><div class="form-group row">\n            <label for="auth_layout_description" class="control-label ltr:ps-3 rtl:pe-3">${jsLang("Description")}</label>\n            <div class="col-sm-12">\n                <textarea id="auth_layout_description" rows="12" class="form-control inputFieldDesign" name="description">${a.data.description}</textarea>\n            </div>\n        </div></div>`),a.required.includes("file")){const l=url+"/resources/views/admin/auth/login_templates/"+e+"/"+a.data.file,t=a.data.file?`<div class="preview-image category-media-preview">\n                    <div class="img-box-two mt-15p">\n                        <img class="fit-boxed" src="${l}" alt="">\n                    </div>\n                </div>`:'<div class="preview-image category-media-preview"></div>';i+=`<div class="mv-form-grid__cell mv-form-grid__cell--full mv-form-section mv-form-section--media mv-m-0 mv-p-0 mv-mb-0"><div class="form-group row">\n            <label for="image-status" class="control-label ltr:ps-3 rtl:pe-3">${jsLang("Background")} / ${jsLang("Upload image")}</label>\n            <div class="col-sm-12">\n                <div class="mv-form-dropzone mv-form-media-field mv-form-picture--category" data-mv-hidden-container="img-container">\n                    <div class="form-group row preview-parent category-media-image-wrap">\n                        <div class="col-sm-12">\n                            <div class="custom-file position-relative media-manager-img has-media-manager category-media-trigger"\n                                data-val="single" data-type="png,jpg,jpeg,webp" data-returntype="ids" id="image-status">\n                                <label class="custom-file-label category-media-label" for="validatedCustomFile">\n                                    <span class="category-media-label__icon" aria-hidden="true"><i class="fa fa-folder-open"></i></span>\n                                    <span class="category-media-label__title">${jsLang("Select from media")}</span>\n                                    <span class="category-media-label__hint">${jsLang("Choose an image from the media library.")}</span>\n                                </label>\n                            </div>\n                            ${t}\n                        </div>\n                    </div>\n                    <div class="ltr:ps-0 rtl:pe-0 d-none" id="img-container" aria-hidden="true"></div>\n                </div>\n            </div>\n        </div></div>`}$("#extra_content").hide(),$("#extra_content").html(i),$("#extra_content").fadeIn(400),$(".preview-button").attr("href",url+"/auth/login?template="+e)});